tpJump4:
html body #travel .tp-jump .wrap{grid-template-columns:repeat(4,minmax(0,1fr))}
html body #travel .tp-jump button:nth-child(1){box-shadow:inset 0 6px 0 #D74949,inset -1px 0 0 #D3D8DC}
html body #travel .tp-jump button:nth-child(2){box-shadow:inset 0 6px 0 #2BA84A,inset -1px 0 0 #D3D8DC}
html body #travel .tp-jump button:nth-child(3){box-shadow:inset 0 6px 0 #6950A1,inset -1px 0 0 #D3D8DC}
html body #travel .tp-jump button:nth-child(4){box-shadow:inset 0 6px 0 #13293C,inset -1px 0 0 #D3D8DC}
@media (max-width:900px){html body #travel .tp-jump .wrap{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:640px){html body #travel .tp-jump .wrap{grid-template-columns:minmax(0,1fr)}}
